misc_JsTools.createKeyInLabel = function(label) {
	var r = new EReg("(.*)\\[(.*)\\](.*)","gi");
	if(!r.match(label)) {
		return $("<span>" + label + "</span>");
	} else {
		var j = $("<span/>");
		j.append(r.matched(1));
		j.append($("<span class=\"key\">" + r.matched(2) + "</span>"));
		j.append(r.matched(3));
		return j;
	}
};
misc_JsTools.createKey = function(kid,keyLabel) {
	if(kid != null) {
		keyLabel = hxd_Key.getKeyName(kid);
	}
	if(keyLabel.toLowerCase() == "shift") {
		keyLabel = "⇧";
	} else if(App.isMac() && keyLabel.toLowerCase() == "ctrl") {
		keyLabel = "⌘";
	}
	if(kid != null) {
		switch(kid) {
		case 192:
			keyLabel = "~";
			break;
		case 222:
			keyLabel = "²";
			break;
		default:
		}
	}
	return $("<span class=\"key\">" + keyLabel + "</span>");
};
misc_JsTools.parseKeysIn = function(jTarget) {
	var funcKeyReg = new EReg("^f[0-9]{1,2}$","gi");
	var content = jTarget.contents();
	var jReplace = $("<div/>");
	content.each(function(idx,e) {
		var j = $(e);
		if(e.nodeType == 3) {
			var _g = 0;
			var _g1 = e.textContent.split(" ");
			while(_g < _g1.length) {
				var k = _g1[_g];
				++_g;
				if(k == null || k.length == 0) {
					continue;
				}
				var jReplace1 = jReplace;
				var _hx_tmp;
				var _hx_tmp1;
				var tmp;
				switch(k.toLowerCase()) {
				case "add":
					tmp = $("<span class=\"key\" title=\"数字键盘 +\">+</span>");
					break;
				case "mouseleft":
					tmp = $("<span class=\"icon mouseleft\" title=\"鼠标左键\"></span>");
					break;
				case "mousemiddle":
					tmp = $("<span class=\"icon mousemiddle\" title=\"鼠标中键\"></span>");
					break;
				case "mouseright":
					tmp = $("<span class=\"icon mouseright\" title=\"鼠标右键\"></span>");
					break;
				case "mousewheel":
					tmp = $("<span class=\"icon mousewheel\" title=\"鼠标滚轮\"></span>");
					break;
				case "\"":case "'":case "+":case "-":case "/":case "on":case "or":case "to":
					tmp = $("<span class=\"misc\">" + k + "</span>");
					break;
				case "sub":
					tmp = $("<span class=\"key\" title=\"数字键盘 -\">-</span>");
					break;
				case "~":
					tmp = $("<span class=\"key\">" + (App.ME.settings.v.navigationKeys == NavigationKeys.Zqsd ? "²" : "~") + "</span>");
					break;
				default:
					_hx_tmp1 = k.charAt(0);
					if(_hx_tmp1 == "(") {
						tmp = $("<span/>").append(k);
					} else {
						_hx_tmp = k.charAt(k.length - 1);
						if(_hx_tmp == ")") {
							tmp = $("<span/>").append(k);
						} else {
							var keyName = k == "macctrl" ? "ctrl" : k.toUpperCase();
							var jKey = $("<span class=\"key\">" + keyName + "</span>");
							switch(k.toLowerCase()) {
							case "alt":case "shift":
								jKey.addClass(k.toLowerCase());
								break;
							case "ctrl":
								jKey.addClass(App.isMac() ? "meta" : "ctrl");
								break;
							case "delete":case "escape":
								jKey.addClass("special");
								break;
							case "macctrl":
								jKey.addClass(App.isMac() ? "ctrl" : "??");
								break;
							default:
								if(funcKeyReg.match(k)) {
									jKey.addClass("special");
								}
							}
							tmp = jKey;
						}
					}
				}
				jReplace1.append(tmp);
			}
		} else {
			jReplace.append(j);
		}
	});
	return jReplace.contents();
};
